export class UI {
  constructor(game, audio) {
    this.game = game;
    this.audio = audio;
    this.selected = null;
    this.choices = [];
    this.returnState = 'playing';
    this.announceTimer = null;
    this.bossShown = false;
    this.hudCache = {};

    game.ui = this;

    this.el = {
      hud: $('hud'), xpfill: $('xpfill'), hpfill: $('hpfill'), hptext: $('hptext'),
      hpregen: $('hpregen'), armorVal: $('armorVal'), levelNum: $('levelNum'),
      timer: $('timer'), kills: $('kills'), goldNum: $('goldNum'),
      bossbar: $('bossbar'), bossName: $('bossName'), bossfill: $('bossfill'), bossPct: $('bossPct'),
      weaponChip: $('weaponChip'), weaponIcon: $('weaponIcon'), weaponName: $('weaponName'), weaponSub: $('weaponSub'),
      announce: $('announce'), toasts: $('toasts'),
      menu: $('menu'), relicCards: $('relicCards'), bestRecord: $('bestRecord'), menuCrest: $('menuCrest'),
      levelup: $('levelup'), luLevel: $('luLevel'), luCards: $('luCards'), btnReroll: $('btnReroll'), rerollCost: $('rerollCost'),
      inventory: $('inventory'), invGoldNum: $('invGoldNum'), equipSlots: $('equipSlots'), statList: $('statList'),
      bagCount: $('bagCount'), bagGrid: $('bagGrid'), itemDetail: $('itemDetail'), autoEquip: $('autoEquip'),
      pause: $('pause'), gameover: $('gameover'), endEyebrow: $('endEyebrow'), endTitle: $('endTitle'),
      endFlavor: $('endFlavor'), endStats: $('endStats'), endBest: $('endBest'),
      joystick: $('joystick'),
    };

    this.bind();
    this.buildMenu();
    this.refreshBest();
    this.refreshMute();
    this.el.autoEquip.checked = game.autoEquip;
  }

  show(node) { node?.classList.remove('hidden'); }
  hide(node) { node?.classList.add('hidden'); }

  bind() {
    $('btnBag').innerHTML = icon('bag');
    $('btnMute').innerHTML = icon('sound');
    $('btnPause').innerHTML = icon('pause');
    $('btnInvClose').innerHTML = icon('cross');
    this.el.menuCrest.innerHTML = icon('skull');

    $('btnBag').addEventListener('click', () => {
      if (this.game.state === 'playing' || this.game.state === 'paused') this.openInventory();
    });
    $('btnMute').addEventListener('click', () => this.toggleMute());
    $('btnPause').addEventListener('click', () => this.pauseGame());
    $('btnResume').addEventListener('click', () => this.resumeGame());
    $('btnPauseBag').addEventListener('click', () => this.openInventory('paused'));
    $('btnQuit').addEventListener('click', () => this.quitToMenu());
    $('btnInvClose').addEventListener('click', () => this.closeInventory());
    $('btnSort').addEventListener('click', () => { this.game.sortBag(); this.renderInventory(); this.audio.ui(); });
    $('btnSellJunk').addEventListener('click', () => {
      const total = this.game.sellJunk();
      if (total) {
        this.selected = null;
        this.renderInventory();
      }
    });
    this.el.autoEquip.addEventListener('change', (e) => {
      this.game.setAutoEquip(e.target.checked);
      this.toast('Auto-equip', e.target.checked ? 'Upgrades are equipped automatically.' : 'Upgrades go to your satchel.', 'magic', 'bag');
    });

    this.el.relicCards.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-relic]');
      if (btn) this.startRun(btn.dataset.relic);
    });

    this.el.luCards.addEventListener('click', (e) => {
      const card = e.target.closest('[data-index]');
      if (card) this.chooseUpgrade(Number(card.dataset.index));
    });
    this.el.btnReroll.addEventListener('click', () => this.reroll());

    this.el.equipSlots.addEventListener('click', (e) => {
      const slotEl = e.target.closest('[data-slot]');
      if (!slotEl) return;
      const item = this.game.equipment[slotEl.dataset.slot];
      if (item) this.select(item, 'equip', slotEl.dataset.slot);
      else {
        this.selected = null;
        this.renderDetail();
        this.audio.ui();
      }
    });

    this.el.bagGrid.addEventListener('click', (e) => {
      const cell = e.target.closest('[data-item]');
      if (!cell) return;
      const item = this.game.inventory.find((i) => i.id === Number(cell.dataset.item));
      if (item) this.select(item, 'bag');
    });

    this.el.itemDetail.addEventListener('click', (e) => {
      const btn = e.target.closest('[data-act]');
      if (!btn || !this.selected) return;
      const { item, from, slot } = this.selected;
      if (btn.dataset.act === 'equip') {
        if (this.game.equipItem(item)) {
          this.selected = { item, from: 'equip', slot: item.slot };
          this.renderInventory();
          this.audio.equip();
        }
      } else if (btn.dataset.act === 'sell') {
        if (this.game.sellItem(item)) {
          this.selected = null;
          this.renderInventory();
        }
      } else if (btn.dataset.act === 'unequip') {
        if (this.game.unequip(slot)) {
          this.selected = { item, from: 'bag', slot: null };
          this.renderInventory();
          this.audio.equip();
        }
      }
    });

    $('btnAgain').addEventListener('click', () => this.startRun(this.game.relic?.id || 'wand'));
    $('btnEndBag').addEventListener('click', () => this.openInventory(this.game.state));
    $('btnMenu').addEventListener('click', () => this.quitToMenu());

    // prevent clicks in empty overlay space from reaching the canvas
    document.querySelectorAll('.overlay').forEach((o) => o.addEventListener('pointerdown', (e) => e.stopPropagation()));
  }

  /* ── menu ──────────────────────────────────────────────────── */
  buildMenu() {
    this.el.relicCards.innerHTML = RELICS.map((r) => `
      <button class="relic" data-relic="${r.id}">
        <span class="relic-ico">${icon(r.icon)}</span>
        <span class="relic-title">${r.title}</span>
        <b>${r.name}</b>
        <span class="relic-desc">${r.desc}</span>
        <span class="relic-perk">${r.perk}</span>
        <span class="relic-cta">Begin the descent</span>
      </button>
    `).join('');
  }

  refreshBest() {
    const best = store.get('cryptfall.best', null);
    if (!best) {
      this.el.bestRecord.textContent = 'No descent recorded yet.';
      return;
    }
    const item = best.itemName ? ` · best find: ${best.itemName}` : '';
    this.el.bestRecord.innerHTML = `BEST DESCENT · ${formatTime(best.time)} · LEVEL ${best.level} · ${formatNum(best.kills)} SLAIN${best.win ? ' · CLEARED' : ''}${item}`;
  }

  refreshMute() {
    $('btnMute').innerHTML = icon(this.audio.muted ? 'mute' : 'sound');
    $('btnMute').classList.toggle('muted', this.audio.muted);
  }

  toggleMute() {
    this.audio.setMuted(!this.audio.muted);
    this.refreshMute();
    this.audio.ui();
  }

  startRun(relicId) {
    this.audio.resume();
    this.hide(this.el.menu);
    this.hide(this.el.gameover);
    this.hide(this.el.levelup);
    this.hide(this.el.inventory);
    this.hide(this.el.pause);
    this.hide(this.el.bossbar);
    this.bossShown = false;
    this.game.start(relicId);
    this.show(this.el.hud);
    this.selected = null;
    this.returnState = 'playing';
    this.updateWeaponChip(true);
    this.announce('DESCEND', 'good');
    this.toast('Relic claimed', `${this.game.equipment.weapon.name} · ${this.game.equipment.weapon.affixes.length ? affixText(this.game.equipment.weapon.affixes[0]) : 'A beginning'}`, 'magic', 'wand', 4200);
  }

  quitToMenu() {
    this.hide(this.el.pause);
    this.hide(this.el.gameover);
    this.hide(this.el.inventory);
    this.hide(this.el.levelup);
    this.hide(this.el.hud);
    this.hide(this.el.bossbar);
    this.game.reset();
    this.game.state = 'menu';
    this.show(this.el.menu);
    this.refreshBest();
    this.audio.ui();
  }

  /* ── HUD ───────────────────────────────────────────────────── */
  updateHUD() {
    const g = this.game;
    const p = g.player;
    const s = g.stats;
    const c = this.hudCache;

    const hpPct = clamp((p.hp / p.maxHp) * 100, 0, 100);
    if (c.hp !== Math.ceil(p.hp) || c.maxHp !== Math.round(p.maxHp)) {
      this.el.hpfill.style.width = hpPct + '%';
      this.el.hptext.textContent = `${Math.ceil(p.hp)} / ${Math.round(p.maxHp)}`;
      this.el.hpfill.classList.toggle('low', hpPct < 30);
      c.hp = Math.ceil(p.hp);
      c.maxHp = Math.round(p.maxHp);
    }
    if (c.regen !== round1(s.regen)) {
      this.el.hpregen.textContent = `+${round1(s.regen)} /s`;
      c.regen = round1(s.regen);
    }
    if (c.armor !== Math.round(s.armor)) {
      this.el.armorVal.textContent = `${Math.round(s.armor)} ARMOR`;
      c.armor = Math.round(s.armor);
    }
    const xpPct = clamp((p.xp / p.xpNext) * 100, 0, 100);
    if (c.xp !== xpPct) {
      this.el.xpfill.style.width = xpPct + '%';
      c.xp = xpPct;
    }
    if (c.level !== p.level) {
      this.el.levelNum.textContent = p.level;
      c.level = p.level;
    }
    const timeStr = formatTime(g.time);
    if (c.time !== timeStr) {
      this.el.timer.textContent = timeStr;
      c.time = timeStr;
    }
    if (c.kills !== g.kills) {
      this.el.kills.innerHTML = `<b>${formatNum(g.kills)}</b> SLAIN`;
      c.kills = g.kills;
    }
    if (c.gold !== g.gold) {
      this.el.goldNum.textContent = formatNum(g.gold);
      c.gold = g.gold;
    }

    const weapon = g.equipment.weapon;
    const wid = weapon ? weapon.id : 'fist';
    if (c.weaponId !== wid) this.updateWeaponChip(true);

    if (g.boss && !g.boss.dead) {
      if (!this.bossShown) this.showBoss(g.boss);
      this.el.bossfill.style.width = `${clamp((g.boss.hp / g.boss.maxHp) * 100, 0, 100)}%`;
      this.el.bossPct.textContent = `${Math.ceil((g.boss.hp / g.boss.maxHp) * 100)}%`;
    } else if (this.bossShown) {
      this.hideBoss();
    }
  }

  updateWeaponChip(force = false) {
    const g = this.game;
    const item = g.equipment.weapon;
    const base = item?.base || { arch: 'fist', name: 'Bare Hands', color: '#cfc7b8' };
    const arch = ARCH[base.arch] || ARCH.fist;
    const iconName = { wand: 'wand', sword: 'sword', bow: 'bow', scythe: 'scythe', fist: 'gloves' }[base.arch] || 'sword';
    this.el.weaponIcon.innerHTML = icon(iconName);
    const color = item ? RARITY[item.rarity].color : '#cfc7b8';
    this.el.weaponIcon.style.color = color;
    this.el.weaponName.textContent = item ? item.name : 'Bare Hands';
    this.el.weaponName.style.color = item ? color : '';
    this.el.weaponSub.textContent = `${arch.name} · ${Math.round(g.stats.weaponDamage || 4)} dmg`;
    this.hudCache.weaponId = item ? item.id : 'fist';
  }

  showBoss(e) {
    this.bossShown = true;
    this.el.bossName.textContent = e.name;
    this.el.bossbar.classList.remove('hidden');
    this.el.bossfill.style.width = '100%';
    this.el.bossPct.textContent = '100%';
  }

  hideBoss() {
    this.bossShown = false;
    this.el.bossbar.classList.add('hidden');
  }

  /* ── announcements & toasts ───────────────────────────────── */
  announce(text, kind = 'good') {
    const el = this.el.announce;
    el.textContent = text;
    el.className = `show ${kind}`;
    clearTimeout(this.announceTimer);
    this.announceTimer = setTimeout(() => {
      el.className = '';
    }, kind === 'boss' || kind === 'victory' ? 3400 : 2300);
  }

  toast(title, sub = '', rarity = 'common', iconName = 'skull', duration = 3400) {
    const rar = RARITY[rarity] || RARITY.common;
    const el = document.createElement('div');
    el.className = 'toast';
    el.style.setProperty('--rar', rar.color);
    el.innerHTML = `
      <span class="toast-ico">${icon(iconName)}</span>
      <span class="toast-body"><b>${title}</b>${sub ? `<span>${sub}</span>` : ''}</span>
    `;
    el.addEventListener('click', () => {
      if (this.game.state === 'playing') this.openInventory();
    });
    this.el.toasts.prepend(el);
    while (this.el.toasts.children.length > 4) this.el.toasts.lastChild.remove();
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 400);
    }, duration);
  }

  lootToast(item, result) {
    const rar = RARITY[item.rarity];
    const slotName = SLOTS[item.slot].name;
    const stat = item.affixes.length ? affixText(item.affixes[0]) : itemImplicitText(item);
    let action = 'Equipped';
    let cls = 'up';
    if (result.action === 'upgraded') {
      action = `Upgraded · +${Math.round(result.compare)} power`;
    } else if (result.action === 'stashed') {
      action = result.compare > 0 ? `Stashed · ▲ ${Math.round(result.compare)} power` : `Stashed · ▼ ${Math.abs(Math.round(result.compare))} power`;
      cls = result.compare > 0 ? 'up' : 'down';
    } else if (result.action === 'sold') {
      action = `Satchel full · sold for ${result.sold}g`;
      cls = 'neutral';
    }
    const el = document.createElement('div');
    el.className = 'toast loot';
    el.style.setProperty('--rar', rar.color);
    el.innerHTML = `
      <span class="toast-ico">${icon(SLOTS[item.slot].icon)}</span>
      <span class="toast-body">
        <b style="color:${rar.color}">${item.name}</b>
        <span class="tmeta">${rar.name} ${slotName} · iLvl ${item.ilvl} · ${item.power} power</span>
        <span class="tstat">${stat}</span>
        <span class="taction ${cls}">${action}</span>
      </span>
    `;
    el.addEventListener('click', () => {
      if (this.game.state === 'playing') this.openInventory();
    });
    this.el.toasts.prepend(el);
    while (this.el.toasts.children.length > 4) this.el.toasts.lastChild.remove();
    setTimeout(() => {
      el.classList.add('out');
      setTimeout(() => el.remove(), 400);
    }, item.rarity === 'legendary' ? 6000 : 4200);
  }

  /* ── level up ─────────────────────────────────────────────── */
  openLevelUp() {
    const g = this.game;
    g.state = 'levelup';
    this.choices = g.getUpgradeChoices();
    this.el.luLevel.textContent = g.player.level;
    const eyebrow = this.el.levelup.querySelector('.eyebrow');
    eyebrow.textContent = g.pendingLevels > 1 ? `THE CRYPT REWARDS YOU · ${g.pendingLevels} BOONS` : 'THE CRYPT REWARDS YOU';
    this.renderChoices();
    this.show(this.el.levelup);
    this.audio.ui();
  }

  renderChoices() {
    const g = this.game;
    this.el.luCards.innerHTML = this.choices.map(({ skill, level }, i) => {
      const maxed = !skill.repeatable && level >= skill.max;
      const pips = skill.repeatable
        ? `<span class="pipnote">Repeatable</span>`
        : Array.from({ length: skill.max }, (_, k) => `<span class="pip ${k < level ? 'on' : k === level ? 'next' : ''}"></span>`).join('');
      return `
        <button class="card ${maxed ? 'maxed' : ''}" data-index="${i}">
          <span class="key">${i + 1}</span>
          <span class="card-ico">${icon(skill.icon)}</span>
          <span class="card-name">${skill.name}</span>
          <span class="card-desc">${skill.desc}</span>
          <span class="pips">${pips}</span>
          ${skill.special === 'item' ? '<span class="cardspecial">RARE+ LOOT</span>' : ''}
        </button>
      `;
    }).join('');
    this.el.rerollCost.textContent = g.rerollCost;
    this.el.btnReroll.disabled = g.gold < g.rerollCost;
    this.el.btnReroll.classList.toggle('disabled', g.gold < g.rerollCost);
  }

  chooseUpgrade(index) {
    if (this.game.state !== 'levelup') return;
    const choice = this.choices[index];
    if (!choice) return;
    this.game.applyUpgrade(choice.skill);
    if (this.game.pendingLevels > 0) {
      this.openLevelUp();
    } else {
      this.hide(this.el.levelup);
      this.game.state = 'playing';
      this.audio.ui();
    }
  }

  reroll() {
    if (this.game.state !== 'levelup') return;
    if (!this.game.rerollChoices()) {
      this.toast('Not enough gold', `Reroll costs ${this.game.rerollCost}g.`, 'common', 'coin');
      return;
    }
    this.choices = this.game.getUpgradeChoices();
    this.renderChoices();
  }

  /* ── inventory ────────────────────────────────────────────── */
  openInventory(fromState = null) {
    const g = this.game;
    if (g.state === 'levelup' || g.state === 'menu') return;
    this.returnState = fromState || (g.state === 'inventory' ? this.returnState : g.state);
    if (this.returnState === 'dead' || this.returnState === 'victory') this.hide(this.el.gameover);
    this.hide(this.el.pause);
    g.state = 'inventory';
    this.renderInventory();
    this.show(this.el.inventory);
    this.audio.ui();
  }

  closeInventory() {
    const g = this.game;
    this.hide(this.el.inventory);
    if (this.returnState === 'dead' || this.returnState === 'victory') {
      g.state = this.returnState;
      this.show(this.el.gameover);
    } else if (this.returnState === 'paused') {
      g.state = 'paused';
      this.show(this.el.pause);
    } else {
      g.state = 'playing';
    }
    this.audio.ui();
  }

  refreshInventory() {
    if (this.game.state === 'inventory') this.renderInventory();
  }

  renderInventory() {
    const g = this.game;
    this.el.invGoldNum.textContent = formatNum(g.gold);
    this.el.bagCount.textContent = `${g.inventory.length} / 30`;
    this.el.autoEquip.checked = g.autoEquip;

    this.renderEquipSlots();
    this.renderStats();
    this.renderBag();
    this.renderDetail();
  }

  renderEquipSlots() {
    const g = this.game;
    this.el.equipSlots.innerHTML = SLOT_ORDER.map((slot) => {
      const item = g.equipment[slot];
      const rar = item ? RARITY[item.rarity] : null;
      const active = this.selected?.from === 'equip' && this.selected?.item === item ? 'sel' : '';
      return `
        <button class="eqslot ${item ? '' : 'empty'} ${active}" data-slot="${slot}" style="--rar:${rar ? rar.color : '#3a3341'}">
          <span class="eqlabel">${SLOTS[slot].name}</span>
          <span class="eqico">${icon(item ? SLOTS[slot].icon : SLOTS[slot].icon)}</span>
          <span class="eqmeta">
            <span class="eqname">${item ? item.name : 'Empty'}</span>
            <span class="eqilvl">${item ? `iLvl ${item.ilvl} · ${item.power} pwr` : '—'}</span>
          </span>
        </button>
      `;
    }).join('');
  }

  renderStats() {
    const g = this.game;
    const s = g.stats;
    const cd = Math.max(0.1, g.weaponCooldown());
    const dps = (s.weaponDamage || 4) * s.damageMult * (1 + (s.crit / 100) * (s.critMult - 1)) / cd;
    const rows = [
      ['Est. DPS', formatNum(dps)],
      ['Damage / hit', formatNum((s.weaponDamage || 4) * s.damageMult)],
      ['Attack rate', `${(1 / cd).toFixed(2)}/s`],
      ['Crit', `${Math.round(s.crit)}% · ${Math.round(s.critMult * 100)}%`],
      ['Max life', Math.round(s.maxHp)],
      ['Armor', `${Math.round(s.armor)} · ${Math.round((s.armor / (s.armor + 100)) * 100)}%`],
      ['Regen', `+${round1(s.regen)}/s`],
      ['Move speed', Math.round(s.speed)],
      ['Cooldown', `-${Math.round(s.cdr)}%`],
      ['Area', `+${Math.round(s.area)}%`],
      ['Magnet', Math.round(s.magnet)],
      ['Luck', `+${Math.round(s.luck)}%`],
      ['Gold find', `+${Math.round(s.gold)}%`],
      ['XP gain', `+${Math.round(s.xp)}%`],
    ];
    this.el.statList.innerHTML = rows.map(([k, v]) => `<div class="statrow"><span>${k}</span><b>${v}</b></div>`).join('');
  }

  renderBag() {
    const g = this.game;
    const cells = g.inventory.map((item) => {
      const rar = RARITY[item.rarity];
      const sel = this.selected?.from === 'bag' && this.selected?.item === item ? 'sel' : '';
      return `
        <button class="bagcell ${sel}" data-item="${item.id}" style="--rar:${rar.color}" title="${item.name}">
          <span class="bico">${icon(SLOTS[item.slot].icon)}</span>
          <span class="bilvl">${item.ilvl}</span>
          <span class="bpower">${item.power}</span>
        </button>
      `;
    }).join('');
    const empties = Math.max(0, 30 - g.inventory.length);
    this.el.bagGrid.innerHTML = cells + '<div class="bagcell empty"></div>'.repeat(empties);
  }

  select(item, from, slot = null) {
    this.selected = { item, from, slot: slot || item.slot };
    this.renderEquipSlots();
    this.renderBag();
    this.renderDetail();
    this.audio.ui();
  }

  renderDetail() {
    const g = this.game;
    const sel = this.selected;
    if (!sel) {
      this.el.itemDetail.innerHTML = '<span class="muted">Select an item to inspect it. Equipped items compare against your satchel.</span>';
      return;
    }
    const item = sel.item;
    const rar = RARITY[item.rarity];
    const equipped = sel.from === 'bag' ? g.equipment[item.slot] : null;
    const compare = equipped ? compareLines(item, equipped) : null;
    const powerDiff = equipped ? item.power - equipped.power : null;

    const affixes = item.affixes.length
      ? item.affixes.map((a) => `<div class="dline">${affixText(a)}</div>`).join('')
      : '<div class="dline muted">No affixes</div>';

    const power = equipped
      ? `<div class="dpower">Power <b>${item.power}</b> <span class="${powerDiff > 0 ? 'up' : powerDiff < 0 ? 'down' : 'neutral'}">${powerDiff > 0 ? '▲ +' : powerDiff < 0 ? '▼ ' : '— '}${powerDiff !== 0 ? Math.abs(Math.round(powerDiff)) : ''}</span></div>`
      : `<div class="dpower">Power <b>${item.power}</b>${sel.from === 'equip' ? '<span class="equipped-tag">EQUIPPED</span>' : ''}</div>`;

    const diffHtml = compare && compare.length
      ? `<div class="dcompare">${compare.map((l) => {
        const delta = l.delta;
        const sign = delta > 0 ? 'up' : delta < 0 ? 'down' : 'neutral';
        const arrow = delta > 0 ? '▲' : delta < 0 ? '▼' : '—';
        const val = l.fmt === 'pct' ? `${Math.round(l.value)}%` : l.fmt === 'dec' ? round1(l.value) : Math.round(l.value);
        return `<div class="statline"><span>${val} ${l.label}</span><span class="${sign}">${arrow} ${Math.abs(Math.round(delta * 10) / 10)}</span></div>`;
      }).join('')}</div>`
      : '';

    const legendary = item.legendaryPower
      ? `<div class="dlegend">
          <div class="dlegend-title">${icon(item.legendaryPower.icon)} ${item.legendaryPower.title}</div>
          <p>${item.legendaryPower.text}</p>
        </div>`
      : '';

    let actions = '';
    if (sel.from === 'bag') {
      actions = `<button class="btn tiny primary" data-act="equip">Equip</button>
                 <button class="btn tiny danger" data-act="sell">Sell · ${item.sellValue}g</button>`;
    } else {
      actions = `<button class="btn tiny" data-act="unequip">Unequip</button>`;
    }

    this.el.itemDetail.innerHTML = `
      <div class="dhead">
        <div class="dname" style="color:${rar.color}">${item.name}</div>
        <div class="dsub">${rar.name} ${SLOTS[item.slot].name} · Item Level ${item.ilvl}</div>
      </div>
      <div class="dimpl">${itemImplicitText(item)}</div>
      <div class="daffixes">${affixes}</div>
      ${legendary}
      ${power}
      ${diffHtml}
      <div class="dactions">${actions}</div>
    `;
  }

  /* ── pause / end ──────────────────────────────────────────── */
  pauseGame() {
    if (this.game.state !== 'playing') return;
    this.game.state = 'paused';
    this.show(this.el.pause);
    this.audio.ui();
  }

  resumeGame() {
    if (this.game.state !== 'paused') return;
    this.hide(this.el.pause);
    this.game.state = 'playing';
    this.audio.resume();
    this.audio.ui();
  }

  showEnd(result, reason) {
    const g = this.game;
    this.hide(this.el.levelup);
    this.hide(this.el.inventory);
    this.hide(this.el.pause);
    this.hideBoss();
    this.el.announce.className = '';

    let eyebrow = 'THE CRYPT CLAIMS YOU';
    let title = 'You Died';
    let flavor = 'The dark keeps what it takes.';
    if (result === 'victory') {
      if (reason === 'boss') {
        eyebrow = 'THE PALE KING FALLS';
        title = 'Crypt Cleared';
        flavor = 'The crown rolls into the dust. For one dawn, the dead are still.';
      } else {
        eyebrow = 'THE NIGHT ENDS';
        title = 'Dawn Breaks';
        flavor = 'You survived until the light. The crypt will remember your name.';
      }
    }
    this.el.endEyebrow.textContent = eyebrow;
    this.el.endTitle.textContent = title;
    this.el.endTitle.className = `endtitle ${result === 'dead' ? 'dead' : 'won'}`;
    this.el.endFlavor.textContent = flavor;

    const stats = [
      ['TIME', formatTime(g.time)],
      ['LEVEL', g.player.level],
      ['SLAIN', formatNum(g.kills)],
      ['GOLD', formatNum(g.gold)],
      ['ITEMS', g.itemsFound],
      ['BEST FIND', g.bestItem ? `${g.bestItem.power} pwr` : '—'],
    ];
    this.el.endStats.innerHTML = stats.map(([k, v]) => `<div class="endstat"><span>${k}</span><b>${v}</b></div>`).join('');

    if (g.bestItem) {
      const rar = RARITY[g.bestItem.rarity];
      this.el.endBest.innerHTML = `<span class="muted">BEST FIND</span> <b style="color:${rar.color}">${g.bestItem.name}</b> <span class="muted">${rar.name} ${SLOTS[g.bestItem.slot].name}</span>`;
    } else {
      this.el.endBest.innerHTML = '<span class="muted">No relics recovered.</span>';
    }

    this.show(this.el.gameover);
    this.refreshBest();
  }
}

import { Game } from './game.js';
import { Renderer } from './render.js';
import { UI } from './ui.js';
import { Audio } from './audio.js';

const canvas = document.getElementById('game');
const audio = new Audio();
const game = new Game(audio);
const renderer = new Renderer(canvas, game);
const ui = new UI(game, audio);

const keys = new Set();
let joystick = null;
let last = performance.now();

const isTyping = (e) => {
  const tag = e.target?.tagName;
  return tag === 'INPUT' || tag === 'TEXTAREA' || tag === 'SELECT';
};

window.addEventListener('keydown', (e) => {
  if (isTyping(e)) return;
  const key = e.key.toLowerCase();
  if (['arrowup', 'arrowdown', 'arrowleft', 'arrowright', ' '].includes(key)) e.preventDefault();

  if (game.state === 'levelup') {
    if (['1', '2', '3'].includes(key) && !e.repeat) {
      ui.chooseUpgrade(Number(key) - 1);
      return;
    }
    if (key === 'r' && !e.repeat) {
      ui.reroll();
      return;
    }
  }

  if (key === 'escape' && !e.repeat) {
    if (game.state === 'inventory') ui.closeInventory();
    else if (game.state === 'paused') ui.resumeGame();
    else if (game.state === 'playing') ui.pauseGame();
    return;
  }
  if (key === 'i' && !e.repeat) {
    if (game.state === 'inventory') ui.closeInventory();
    else if (game.state === 'playing' || game.state === 'paused') ui.openInventory();
    return;
  }
  if (key === 'm' && !e.repeat) {
    ui.toggleMute();
    return;
  }
  if (key === 'p' && !e.repeat && (game.state === 'playing' || game.state === 'paused')) {
    if (game.state === 'playing') ui.pauseGame();
    else ui.resumeGame();
    return;
  }
  keys.add(key);
});

window.addEventListener('keyup', (e) => {
  keys.delete(e.key.toLowerCase());
});

window.addEventListener('blur', () => {
  keys.clear();
  endJoystick();
});

/* ── floating touch joystick ─────────────────────────────────── */
const joyEl = document.getElementById('joystick');
const knobEl = joyEl.querySelector('.knob');
const MAX_DIST = 58;

function startJoystick(e) {
  if (game.state !== 'playing') return;
  audio.resume();
  joystick = { id: e.pointerId, ox: e.clientX, oy: e.clientY, x: 0, y: 0 };
  canvas.setPointerCapture?.(e.pointerId);
  joyEl.classList.remove('hidden');
  joyEl.style.left = `${e.clientX}px`;
  joyEl.style.top = `${e.clientY}px`;
  knobEl.style.transform = 'translate(-50%, -50%)';
  updateJoystick(e);
}

function updateJoystick(e) {
  if (!joystick || e.pointerId !== joystick.id) return;
  let dx = e.clientX - joystick.ox;
  let dy = e.clientY - joystick.oy;
  const d = Math.hypot(dx, dy);
  if (d > MAX_DIST) {
    dx = (dx / d) * MAX_DIST;
    dy = (dy / d) * MAX_DIST;
  }
  joystick.x = dx / MAX_DIST;
  joystick.y = dy / MAX_DIST;
  knobEl.style.transform = `translate(calc(-50% + ${dx}px), calc(-50% + ${dy}px))`;
}

function endJoystick() {
  if (!joystick) return;
  joystick = null;
  joyEl.classList.add('hidden');
}

canvas.addEventListener('pointerdown', (e) => {
  e.preventDefault();
  startJoystick(e);
});
canvas.addEventListener('pointermove', (e) => {
  if (joystick) {
    e.preventDefault();
    updateJoystick(e);
  }
});
canvas.addEventListener('pointerup', (e) => {
  if (joystick && e.pointerId === joystick.id) endJoystick();
});
canvas.addEventListener('pointercancel', endJoystick);
canvas.addEventListener('pointerleave', (e) => {
  if (joystick && e.pointerId === joystick.id) endJoystick();
});
canvas.addEventListener('contextmenu', (e) => e.preventDefault());

/* ── main loop ───────────────────────────────────────────────── */
function updateInput() {
  let x = 0;
  let y = 0;
  if (keys.has('a') || keys.has('arrowleft')) x -= 1;
  if (keys.has('d') || keys.has('arrowright')) x += 1;
  if (keys.has('w') || keys.has('arrowup')) y -= 1;
  if (keys.has('s') || keys.has('arrowdown')) y += 1;
  if (joystick) {
    x = joystick.x;
    y = joystick.y;
  }
  const len = Math.hypot(x, y);
  if (len > 1) {
    x /= len;
    y /= len;
  }
  game.input.x = x;
  game.input.y = y;
}

function frame(now) {
  const dt = Math.min(0.05, Math.max(0.0001, (now - last) / 1000));
  last = now;
  updateInput();
  game.update(dt);
  renderer.render(now);
  if (game.state !== 'menu') ui.updateHUD();
  requestAnimationFrame(frame);
}

window.addEventListener('resize', () => renderer.resize());
window.addEventListener('orientationchange', () => setTimeout(() => renderer.resize(), 120));

document.addEventListener('visibilitychange', () => {
  if (document.hidden && game.state === 'playing') ui.pauseGame();
});

// first interaction unlocks audio
const unlock = () => {
  audio.resume();
  window.removeEventListener('pointerdown', unlock);
  window.removeEventListener('keydown', unlock);
};
window.addEventListener('pointerdown', unlock);
window.addEventListener('keydown', unlock);

requestAnimationFrame(frame);

content.text:
Now styles.css. This is a big one. Need polish. Let's plan CSS variables and components.

Palette:
--bg #07060a
--panel #141019 / #1a1420
--ink #e9e0cf
--muted #9c9080
--gold #d8b26a
--gold-bright #f2d18b
--bronze #5a4630
--line rgba(216,178,106,.22)
--red #c0393f

Fonts:
--serif: 'Palatino Linotype','Book Antiqua',Palatino,Georgia,serif
--sans: system-ui,-apple-system,'Segoe UI',Roboto,sans-serif

Base:
*,*::before,*::after {box-sizing:border-box}
html,body {height:100%; margin:0; background:var(--bg); color:var(--ink); font-family:var(--sans); overflow:hidden; overscroll-behavior:none;}
body {touch-action:none; -webkit-user-select:none; user-select:none;}
button {font:inherit;color:inherit;background:none;border:0;cursor:pointer;}
.hidden{display:none!important;}
.ico {width:1em;height:1em;display:block;}

#app position fixed inset 0.
canvas absolute inset 0 width/height 100%; touch-action:none; cursor:crosshair.

HUD:
#hud {position:absolute;inset:0;pointer-events:none; z-index:10; padding: max(10px, env(safe-area-inset-top)) ...}
#xpbar {position:absolute;top:0;left:0;right:0;height:4px;background:rgba(0,0,0,.65);}
#xpfill {height:100%;width:0;background:linear-gradient(90deg,#3c8fd6,#8ff0ff); box-shadow:0 0 8px rgba(127,230,255,.6); transition:width .12s linear;}
.hud-top {position:absolute;top:calc(10px + env(safe-area-inset-top));left:calc(14px + env(safe-area-inset-left));right:calc(14px + env(safe-area-inset-right));display:flex;align-items:flex-start;justify-content:space-between;gap:10px;}
.hud-left {display:flex;align-items:center;gap:10px; pointer-events:none;}
#levelMedal {width:48px;height:48px;border-radius:50%; display:grid;place-items:center; background:radial-gradient(circle at 40% 30%, #3b2f1e, #17111b 70%); border:1px solid #7a5c32; box-shadow:0 0 0 2px #100c14, inset 0 0 12px rgba(216,178,106,.15), 0 4px 10px rgba(0,0,0,.5); position:relative;}
#levelMedal::after {content:'';position:absolute;inset:-4px;border-radius:50%;border:1px solid rgba(216,178,106,.18);}
#levelNum {font-family:var(--serif);font-size:20px;font-weight:700;color:#f2d18b;line-height:1;}
#levelMedal small {font-size:7px;letter-spacing:.18em;color:#9c8458;margin-top:-2px;}
.bars {display:flex;flex-direction:column;gap:4px;}
.hpbar {position:relative;width:clamp(140px,22vw,260px);height:19px;background:#160d10;border:1px solid #5c3a36;border-radius:2px;box-shadow:inset 0 2px 6px rgba(0,0,0,.7), 0 0 0 1px rgba(0,0,0,.5);overflow:hidden;}
#hpfill {height:100%;width:100%;background:linear-gradient(180deg,#c0393f,#6d141b);box-shadow:inset 0 1px 0 rgba(255,160,160,.35);transition:width .15s ease-out;}
#hpfill.low {animation:hppulse 1s infinite;}
@keyframes hppulse {50%{filter:brightness(1.5)}}
#hptext {position:absolute;inset:0;display:grid;place-items:center;font-size:10px;letter-spacing:.08em;color:#f3e7df;text-shadow:0 1px 2px #000;font-variant-numeric:tabular-nums;}
.hpsub {display:flex;gap:12px;font-size:8px;letter-spacing:.13em;color:#8b7c6c;text-transform:uppercase;padding-left:2px;}
.hud-center {position:absolute;left:50%;transform:translateX(-50%);text-align:center;}
#timer {font-family:var(--serif);font-size:clamp(26px,3.4vw,40px);line-height:1;letter-spacing:.08em;color:#f0e4cd;text-shadow:0 2px 12px rgba(0,0,0,.9),0 0 22px rgba(216,178,106,.15);font-variant-numeric:tabular-nums;}
#kills {font-size:8px;letter-spacing:.24em;color:#8b7c6c;margin-top:3px;}
#kills b{color:#d8b26a;font-weight:600;}
.hud-right {display:flex;align-items:center;gap:8px;pointer-events:auto;}
#gold {display:flex;align-items:center;gap:6px;padding:6px 10px;background:rgba(15,12,18,.75);border:1px solid rgba(216,178,106,.22);border-radius:2px;font-size:12px;color:#f2d18b;font-variant-numeric:tabular-nums;backdrop-filter:blur(4px);}
.coin {width:9px;height:9px;border-radius:50%;background:radial-gradient(circle at 35% 30%,#ffe9a8,#c99a34 60%,#7a5a18);display:inline-block;box-shadow:0 0 6px rgba(255,200,80,.35);}
.iconbtn {width:36px;height:36px;display:grid;place-items:center;background:rgba(18,14,22,.82);border:1px solid rgba(216,178,106,.22);border-radius:2px;color:#c9b48a;transition:.15s;backdrop-filter:blur(4px);}
.iconbtn .ico{width:17px;height:17px;}
.iconbtn:hover{color:#f2d18b;border-color:rgba(216,178,106,.6);background:rgba(40,30,24,.9);}
.iconbtn.muted{color:#6d6357;}
#bossbar {position:absolute;top:calc(78px + env(safe-area-inset-top));left:50%;transform:translateX(-50%);width:min(560px,72vw);}
.bossname{display:flex;justify-content:space-between;font-family:var(--serif);font-size:11px;letter-spacing:.2em;color:#e8b9a0;text-transform:uppercase;margin-bottom:4px;text-shadow:0 2px 6px #000;}
.bossTrack{height:9px;background:#170e12;border:1px solid #5c3a36;box-shadow:inset 0 2px 5px rgba(0,0,0,.8);overflow:hidden;}
#bossfill{height:100%;width:100%;background:linear-gradient(90deg,#7d1d26,#d0503c 60%,#ffb15e);box-shadow:0 0 12px rgba(255,120,60,.4);transition:width .1s linear;}
#weaponChip{position:absolute;left:calc(16px + env(safe-area-inset-left));bottom:calc(16px + env(safe-area-inset-bottom));display:flex;align-items:center;gap:9px;padding:7px 12px 7px 9px;background:linear-gradient(180deg,rgba(24,18,28,.86),rgba(12,9,15,.86));border:1px solid rgba(216,178,106,.18);border-radius:3px;backdrop-filter:blur(5px);max-width:260px;}
.chipico{display:grid;place-items:center;width:32px;height:32px;border:1px solid rgba(216,178,106,.18);background:#100c14;}
.chipico .ico{width:19px;height:19px;}
#weaponChip b{display:block;font-family:var(--serif);font-size:12px;font-weight:600;letter-spacing:.03em;line-height:1.15;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:190px;}
#weaponChip small{display:block;font-size:8px;letter-spacing:.1em;color:#8b7c6c;text-transform:uppercase;margin-top:2px;}
#hint{position:absolute;bottom:calc(18px + env(safe-area-inset-bottom));left:50%;transform:translateX(-50%);font-size:9px;letter-spacing:.16em;color:#6b6054;text-transform:uppercase;white-space:nowrap;}
#announce{position:absolute;top:24%;left:50%;transform:translate(-50%,-10px);font-family:var(--serif);font-size:clamp(22px,3.6vw,44px);letter-spacing:.14em;text-align:center;color:#f2d18b;opacity:0;pointer-events:none;text-shadow:0 0 30px rgba(255,180,80,.35),0 4px 18px #000;transition:opacity .4s, transform .4s;white-space:nowrap;}
#announce.show{opacity:1;transform:translate(-50%,0);}
#announce.boss{color:#ff8a6a;text-shadow:0 0 30px rgba(255,60,30,.5),0 4px 18px #000;}
#announce.legendary{color:#ffb15e;text-shadow:0 0 34px rgba(255,130,40,.65),0 4px 18px #000;}
#announce.victory{color:#ffe6a8;}
#announce.good{color:#e8d6a8;}

#joystick{position:fixed;width:132px;height:132px;transform:translate(-50%,-50%);pointer-events:none;z-index:15;}
#joystick .stick{position:absolute;inset:0;border-radius:50%;border:1px solid rgba(216,178,106,.22);background:radial-gradient(circle,rgba(216,178,106,.06),rgba(0,0,0,.18) 70%);box-shadow:inset 0 0 24px rgba(0,0,0,.4);}
#joystick .knob{position:absolute;left:50%;top:50%;width:48px;height:48px;border-radius:50%;background:radial-gradient(circle at 38% 32%,rgba(242,209,139,.5),rgba(90,70,48,.5));border:1px solid rgba(242,209,139,.45);box-shadow:0 0 18px rgba(216,178,106,.18);transform:translate(-50%,-50%);}

Toasts:
#toasts{position:fixed;top:calc(88px + env(safe-area-inset-top));right:calc(14px + env(safe-area-inset-right));display:flex;flex-direction:column;gap:8px;z-index:20;width:min(310px,72vw);pointer-events:none;}
.toast{pointer-events:auto;display:flex;gap:10px;padding:10px 12px;background:linear-gradient(180deg,rgba(24,18,26,.96),rgba(12,9,14,.96));border:1px solid color-mix(in srgb,var(--rar) 38%,transparent);border-left:2px solid var(--rar);box-shadow:0 8px 24px rgba(0,0,0,.55);animation:toastin .28s cubic-bezier(.2,.8,.3,1);cursor:pointer;position:relative;}
.toast::before{content:'';position:absolute;inset:0;background:linear-gradient(90deg,color-mix(in srgb,var(--rar) 8%,transparent),transparent 60%);pointer-events:none;}
.toast.out{animation:toastout .35s forwards;}
@keyframes toastin{from{opacity:0;transform:translateX(24px)}to{opacity:1;transform:none}}
@keyframes toastout{to{opacity:0;transform:translateX(24px)}}
.toast-ico{flex:0 0 30px;height:30px;display:grid;place-items:center;border:1px solid color-mix(in srgb,var(--rar) 30%,transparent);color:var(--rar);background:rgba(0,0,0,.25);}
.toast-ico .ico{width:17px;height:17px;}
.toast-body{display:flex;flex-direction:column;gap:2px;min-width:0;}
.toast-body b{font-family:var(--serif);font-size:12px;letter-spacing:.02em;color:#efe4cf;line-height:1.2;}
.toast-body span{font-size:9.5px;color:#9c9080;letter-spacing:.03em;line-height:1.35;}
.toast.loot .toast-body b{font-size:13px;}
.tmeta{color:#8b7c6c !important;text-transform:uppercase;letter-spacing:.08em !important;font-size:8px !important;}
.tstat{color:#c9b48a !important;}
.taction{font-weight:600;letter-spacing:.05em !important;text-transform:uppercase;font-size:8.5px !important;}
.taction.up{color:#7fdc8a !important;}
.taction.down{color:#e07a7a !important;}
.taction.neutral{color:#b9a77f !important;}

Overlays:
.overlay{position:fixed;inset:0;display:grid;place-items:center;padding:calc(18px + env(safe-area-inset-top)) calc(18px + env(safe-area-inset-right)) calc(18px + env(safe-area-inset-bottom)) calc(18px + env(safe-area-inset-left));background:rgba(5,4,9,.78);backdrop-filter:blur(7px);z-index:50;overflow:auto;overscroll-behavior:contain;touch-action:pan-y;}
#menu{z-index:80;background:radial-gradient(ellipse at 50% 40%,rgba(20,14,26,.55),rgba(4,3,7,.92));backdrop-filter:none;}
#levelup{z-index:55;}
#inventory{z-index:70;}
#pause{z-index:60;}
#gameover{z-index:65;}
.panel{position:relative;background:linear-gradient(180deg,#191320 0%,#100c15 100%);border:1px solid rgba(216,178,106,.28);box-shadow:0 30px 80px rgba(0,0,0,.75),inset 0 1px 0 rgba(255,230,180,.06);}
.panel::before,.panel::after{content:'';position:absolute;width:16px;height:16px;border-color:rgba(216,178,106,.55);border-style:solid;pointer-events:none;}
.panel::before{left:-1px;top:-1px;border-width:1px 0 0 1px;}
.panel::after{right:-1px;bottom:-1px;border-width:0 1px 1px 0;}
.eyebrow{font-size:8px;letter-spacing:.34em;color:#9c8458;text-transform:uppercase;margin-bottom:6px;}
h2{font-family:var(--serif);font-weight:400;font-size:clamp(24px,3.6vw,38px);letter-spacing:.06em;margin:0 0 14px;color:#f0e4cd;}
.muted{color:#8b7c6c;font-size:10px;letter-spacing:.08em;}
.center{text-align:center;}

Menu:
.menuoverlay{place-items:center;}
.menu-inner{width:min(1080px,94vw);text-align:center;padding:20px 0 10px;animation:fadein .6s ease;}
@keyframes fadein{from{opacity:0;transform:translateY(10px)}to{opacity:1;transform:none}}
.crest{width:64px;height:64px;margin:0 auto 10px;border-radius:50%;display:grid;place-items:center;border:1px solid rgba(216,178,106,.4);background:radial-gradient(circle at 40% 30%,#3a2c1c,#100c14 70%);color:#d8b26a;box-shadow:0 0 30px rgba(216,178,106,.12),inset 0 0 18px rgba(0,0,0,.6);}
.crest .ico{width:30px;height:30px;}
.title{font-family:var(--serif);font-size:clamp(56px,11vw,124px);font-weight:400;line-height:.92;letter-spacing:.06em;margin:0;color:#efe2c6;text-shadow:0 0 60px rgba(216,178,106,.18),0 8px 40px rgba(0,0,0,.9);}
.title span{color:#d8b26a;display:inline-block;}
.tagline{font-family:var(--serif);font-size:clamp(14px,1.8vw,20px);color:#c9b48a;letter-spacing:.05em;margin:14px 0 6px;}
.lede{max-width:560px;margin:0 auto;color:#8b7c6c;font-size:12px;line-height:1.6;letter-spacing:.02em;}
.relic-label{font-size:8px;letter-spacing:.4em;color:#7d6a4c;text-transform:uppercase;margin:30px 0 12px;}
.relics{display:grid;grid-template-columns:repeat(3,1fr);gap:14px;max-width:900px;margin:0 auto;}
.relic{position:relative;display:flex;flex-direction:column;align-items:center;gap:5px;padding:22px 18px 16px;background:linear-gradient(180deg,rgba(28,21,32,.9),rgba(12,9,15,.92));border:1px solid rgba(216,178,106,.16);text-align:center;transition:.2s;overflow:hidden;}
.relic::after{content:'';position:absolute;inset:0;background:radial-gradient(circle at 50% 0%,rgba(216,178,106,.09),transparent 65%);opacity:0;transition:.2s;}
.relic:hover{border-color:rgba(216,178,106,.65);transform:translateY(-4px);box-shadow:0 16px 40px rgba(0,0,0,.5),0 0 0 1px rgba(216,178,106,.12);}
.relic:hover::after{opacity:1;}
.relic-ico{width:46px;height:46px;display:grid;place-items:center;border:1px solid rgba(216,178,106,.3);border-radius:50%;color:#e8cf9a;margin-bottom:4px;background:radial-gradient(circle at 40% 30%,#2a2118,#100c14);}
.relic-ico .ico{width:24px;height:24px;}
.relic-title{font-size:7.5px;letter-spacing:.3em;color:#8b7c6c;text-transform:uppercase;}
.relic b{font-family:var(--serif);font-weight:400;font-size:21px;color:#efe2c6;letter-spacing:.03em;}
.relic-desc{font-size:11px;color:#9c9080;line-height:1.5;max-width:220px;min-height:48px;}
.relic-perk{font-size:9px;color:#7fdc8a;letter-spacing:.08em;text-transform:uppercase;}
.relic-cta{margin-top:8px;font-size:8px;letter-spacing:.26em;color:#d8b26a;text-transform:uppercase;border-top:1px solid rgba(216,178,106,.15);padding-top:9px;width:100%;}
.menu-foot{display:flex;flex-direction:column;gap:4px;margin-top:24px;font-size:9px;letter-spacing:.1em;}
#bestRecord{color:#b39a6a;}

Level up:
.levelpanel{width:min(980px,95vw);padding:26px 26px 20px;text-align:center;}
.cards{display:grid;grid-template-columns:repeat(3,1fr);gap:12px;margin:18px 0 14px;}
.card{position:relative;display:flex;flex-direction:column;align-items:center;gap:7px;padding:22px 14px 16px;background:linear-gradient(180deg,rgba(30,23,35,.95),rgba(13,10,16,.95));border:1px solid rgba(216,178,106,.16);transition:.18s;min-height:210px;}
.card:hover,.card:focus-visible{border-color:rgba(216,178,106,.7);transform:translateY(-4px);background:linear-gradient(180deg,rgba(40,30,42,.98),rgba(16,12,19,.98));outline:none;box-shadow:0 14px 34px rgba(0,0,0,.5);}
.card .key{position:absolute;top:8px;left:10px;font-size:9px;color:#6b6054;border:1px solid rgba(216,178,106,.18);width:18px;height:18px;display:grid;place-items:center;border-radius:2px;}
.card-ico{width:52px;height:52px;display:grid;place-items:center;border-radius:50%;border:1px solid rgba(216,178,106,.28);color:#e8cf9a;background:radial-gradient(circle at 40% 30%,#30251a,#100c14 70%);box-shadow:0 0 24px rgba(216,178,106,.08);}
.card-ico .ico{width:26px;height:26px;}
.card-name{font-family:var(--serif);font-size:19px;color:#f0e4cd;letter-spacing:.03em;}
.card-desc{font-size:10.5px;line-height:1.5;color:#9c9080;max-width:200px;}
.pips{display:flex;gap:4px;margin-top:auto;padding-top:10px;flex-wrap:wrap;justify-content:center;}
.pip{width:14px;height:3px;background:#2c2533;}
.pip.on{background:#d8b26a;}
.pip.next{background:#6b5a3e;}
.pipnote{font-size:8px;letter-spacing:.2em;color:#7d6a4c;text-transform:uppercase;}
.cardspecial{font-size:7.5px;letter-spacing:.2em;color:#ff8a3d;border:1px solid rgba(255,138,61,.3);padding:2px 6px;}
.lufoot{display:flex;align-items:center;justify-content:space-between;gap:14px;margin-top:6px;}
.lufoot .muted{font-size:9px;letter-spacing:.16em;text-transform:uppercase;}

Buttons:
.btn{display:inline-flex;align-items:center;justify-content:center;gap:6px;padding:10px 18px;background:linear-gradient(180deg,#2a2030,#17111c);border:1px solid rgba(216,178,106,.28);color:#d8c7a5;font-size:10px;letter-spacing:.16em;text-transform:uppercase;transition:.16s;border-radius:2px;}
.btn:hover{border-color:rgba(216,178,106,.7);color:#f2d18b;background:linear-gradient(180deg,#392b3c,#1e1524);}
.btn.primary{background:linear-gradient(180deg,#5c4726,#2c2114);border-color:rgba(242,209,139,.6);color:#ffe6a8;box-shadow:0 0 22px rgba(216,178,106,.12),inset 0 1px 0 rgba(255,230,180,.2);}
.btn.primary:hover{background:linear-gradient(180deg,#77602f,#3a2b18);}
.btn.ghost{background:transparent;border-color:rgba(216,178,106,.16);color:#9c9080;}
.btn.tiny{padding:6px 10px;font-size:8px;letter-spacing:.1em;}
.btn.danger{border-color:rgba(192,57,63,.35);color:#e09090;}
.btn.danger:hover{border-color:rgba(230,90,90,.7);color:#ffb0b0;background:rgba(80,20,24,.35);}
.btn:disabled,.btn.disabled{opacity:.4;cursor:not-allowed;}
.btn .ico{width:13px;height:13px;}
.stack{display:flex;flex-direction:column;gap:9px;margin-top:18px;}
.stack.row{flex-direction:row;flex-wrap:wrap;justify-content:center;}

Small panels:
.smallpanel{width:min(480px,94vw);padding:28px;text-align:center;}
.smallpanel h2{margin-bottom:8px;}
.smallpanel .stack{max-width:280px;margin-left:auto;margin-right:auto;}
.endpanel{width:min(640px,94vw);}
.endtitle{font-size:clamp(36px,6vw,56px);letter-spacing:.05em;margin:4px 0 8px;}
.endtitle.dead{color:#d45a5a;text-shadow:0 0 40px rgba(180,30,30,.25);}
.endtitle.won{color:#f2d18b;text-shadow:0 0 40px rgba(255,200,100,.25);}
.endstats{display:grid;grid-template-columns:repeat(3,1fr);gap:1px;background:rgba(216,178,106,.12);border:1px solid rgba(216,178,106,.16);margin:18px 0 10px;}
.endstat{background:#120e17;padding:11px 8px;display:flex;flex-direction:column;gap:3px;}
.endstat span{font-size:7.5px;letter-spacing:.22em;color:#7d6a4c;text-transform:uppercase;}
.endstat b{font-family:var(--serif);font-size:19px;font-weight:400;color:#f0e4cd;}
.endbest{font-size:10px;letter-spacing:.05em;margin-bottom:4px;line-height:1.6;}

Inventory:
.invpanel{width:min(1120px,96vw);height:min(780px,92vh);display:flex;flex-direction:column;padding:20px 22px 18px;}
.invhead{display:flex;justify-content:space-between;align-items:flex-start;gap:14px;padding-bottom:12px;border-bottom:1px solid rgba(216,178,106,.14);}
.invhead h2{margin:0;}
.invhead-right{display:flex;align-items:center;gap:10px;}
#invGold{display:flex;align-items:center;gap:6px;font-size:12px;color:#f2d18b;padding:6px 10px;border:1px solid rgba(216,178,106,.2);background:rgba(0,0,0,.25);font-variant-numeric:tabular-nums;}
.invbody{display:grid;grid-template-columns:380px 1fr;gap:22px;flex:1;min-height:0;padding-top:14px;}
.doll{display:flex;flex-direction:column;min-height:0;overflow:auto;padding-right:4px;}
.doll-title{font-size:7.5px;letter-spacing:.28em;color:#7d6a4c;text-transform:uppercase;margin:0 0 7px;}
.slots{display:grid;grid-template-columns:1fr 1fr;gap:6px;margin-bottom:16px;}
.eqslot{display:flex;align-items:center;gap:8px;padding:7px 8px;background:linear-gradient(180deg,rgba(28,21,32,.85),rgba(14,10,17,.85));border:1px solid color-mix(in srgb,var(--rar) 34%,transparent);border-left:2px solid var(--rar);text-align:left;transition:.15s;min-width:0;}
.eqslot:hover,.eqslot.sel{border-color:color-mix(in srgb,var(--rar) 80%,transparent);background:rgba(42,31,45,.9);}
.eqslot.empty{border-color:rgba(216,178,106,.1);border-left-color:#2c2533;}
.eqslot:nth-child(1){grid-column:span 2;}
.eqico{flex:0 0 28px;height:28px;display:grid;place-items:center;color:var(--rar);border:1px solid color-mix(in srgb,var(--rar) 22%,transparent);background:rgba(0,0,0,.25);}
.eqico .ico{width:16px;height:16px;}
.eqslot.empty .eqico{color:#4b4351;}
.eqmeta{display:flex;flex-direction:column;min-width:0;gap:1px;}
.eqlabel{font-size:6.5px;letter-spacing:.2em;color:#7d6a4c;text-transform:uppercase;position:absolute;margin-top:-21px;margin-left:30px;opacity:0;pointer-events:none;}
.eqname{font-family:var(--serif);font-size:11px;color:#e6d9c2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:250px;}
.eqilvl{font-size:8px;color:#8b7c6c;letter-spacing:.05em;}
.stats{display:grid;grid-template-columns:1fr 1fr;gap:3px 14px;padding-bottom:8px;}
.statrow{display:flex;justify-content:space-between;gap:6px;font-size:9.5px;color:#9c9080;padding:2px 0;border-bottom:1px dotted rgba(216,178,106,.07);}
.statrow b{color:#d8c7a5;font-weight:500;font-variant-numeric:tabular-nums;}

.satchel{display:flex;flex-direction:column;min-height:0;}
.satchel-top{display:flex;justify-content:space-between;align-items:center;font-size:9px;letter-spacing:.16em;color:#8b7c6c;text-transform:uppercase;margin-bottom:8px;}
.satchel-actions{display:flex;gap:6px;}
.baggrid{display:grid;grid-template-columns:repeat(6,1fr);gap:6px;}
.bagcell{position:relative;aspect-ratio:1;background:linear-gradient(180deg,rgba(26,20,30,.9),rgba(12,9,15,.9));border:1px solid color-mix(in srgb,var(--rar) 30%,transparent);border-top:2px solid var(--rar);display:grid;place-items:center;transition:.12s;overflow:hidden;}
.bagcell:hover,.bagcell.sel{border-color:color-mix(in srgb,var(--rar) 90%,transparent);background:rgba(44,32,48,.95);transform:translateY(-2px);box-shadow:0 6px 16px rgba(0,0,0,.4);}
.bagcell.empty{border-color:rgba(216,178,106,.07);border-top-color:rgba(216,178,106,.07);background:rgba(9,7,11,.6);pointer-events:none;}
.bico{color:var(--rar);display:grid;place-items:center;}
.bico .ico{width:23px;height:23px;}
.bilvl{position:absolute;left:4px;bottom:2px;font-size:7px;color:#8b7c6c;}
.bpower{position:absolute;right:4px;bottom:2px;font-size:7px;color:#a89678;}
.itemdetail{margin-top:10px;flex:1;min-height:150px;max-height:290px;overflow:auto;background:linear-gradient(180deg,rgba(22,17,26,.9),rgba(11,8,14,.9));border:1px solid rgba(216,178,106,.16);padding:12px 14px;display:flex;flex-direction:column;gap:7px;}
.dhead{border-bottom:1px solid rgba(216,178,106,.1);padding-bottom:6px;}
.dname{font-family:var(--serif);font-size:17px;letter-spacing:.02em;line-height:1.2;}
.dsub{font-size:8px;letter-spacing:.14em;color:#8b7c6c;text-transform:uppercase;margin-top:2px;}
.dimpl{font-size:11px;color:#e8dcc0;font-weight:600;}
.daffixes{display:flex;flex-direction:column;gap:2px;}
.dline{font-size:10px;color:#8fc4ff;}
.dline.muted{color:#6b6054;}
.dlegend{background:rgba(255,138,61,.06);border:1px solid rgba(255,138,61,.25);padding:7px 9px;}
.dlegend-title{display:flex;align-items:center;gap:5px;color:#ffb15e;font-family:var(--serif);font-size:12px;letter-spacing:.03em;}
.dlegend-title .ico{width:13px;height:13px;}
.dlegend p{margin:3px 0 0;font-size:9px;color:#c9a58a;line-height:1.45;}
.dpower{display:flex;align-items:center;gap:7px;font-size:9px;letter-spacing:.12em;color:#8b7c6c;text-transform:uppercase;border-top:1px solid rgba(216,178,106,.1);padding-top:6px;margin-top:auto;}
.dpower b{font-family:var(--serif);font-size:15px;color:#f0e4cd;letter-spacing:0;}
.dpower .up,.dcompare .up{color:#7fdc8a;}
.dpower .down,.dcompare .down{color:#e07a7a;}
.dpower .neutral{color:#8b7c6c;}
.equipped-tag{margin-left:auto;font-size:7px;letter-spacing:.18em;color:#8b7c6c;border:1px solid rgba(216,178,106,.2);padding:2px 5px;}
.dcompare{display:grid;grid-template-columns:1fr 1fr;gap:1px 12px;border-top:1px dotted rgba(216,178,106,.1);padding-top:5px;}
.statline{display:flex;justify-content:space-between;gap:6px;font-size:8.5px;color:#9c9080;}
.statline .up{color:#7fdc8a;}
.statline .down{color:#e07a7a;}
.statline .neutral{color:#6b6054;}
.dactions{display:flex;gap:6px;margin-top:4px;}
.dactions .btn{flex:1;}
.autoequip{display:flex;align-items:center;gap:7px;margin-top:8px;font-size:8.5px;letter-spacing:.1em;color:#8b7c6c;text-transform:uppercase;cursor:pointer;}
.autoequip input{accent-color:#b08a44;width:12px;height:12px;}

Responsive:
@media (max-width: 900px) {
 .invbody{grid-template-columns:1fr; overflow:auto;}
 .doll{overflow:visible;}
 .invpanel{height:min(860px,94vh);}
 .baggrid{grid-template-columns:repeat(5,1fr);}
 .itemdetail{max-height:none;}
 .cards{grid-template-columns:1fr; max-height:56vh; overflow:auto; padding:2px;}
 .card{min-height:0;flex-direction:row;flex-wrap:wrap;justify-content:flex-start;text-align:left;align-items:center;padding:12px 14px;gap:4px 12px;}
 .card .key{position:static;order:9;margin-left:auto;}
 .card-ico{width:38px;height:38px;flex:0 0 38px;}
 .card-ico .ico{width:20px;height:20px;}
 .card-name{font-size:16px;}
 .card-desc{width:100%;max-width:none;font-size:10px;padding-left:50px;}
 .pips{padding-left:50px;justify-content:flex-start;margin-top:0;}
 .cardspecial{margin-left:50px;}
 .relics{grid-template-columns:1fr;max-width:460px;}
 .relic{flex-direction:row;flex-wrap:wrap;text-align:left;align-items:center;padding:14px;gap:2px 12px;}
 .relic-ico{flex:0 0 40px;width:40px;height:40px;margin:0;}
 .relic b{font-size:17px;}
 .relic-desc{min-height:0;max-width:none;flex:1 1 100%;padding-left:52px;}
 .relic-perk{padding-left:52px;}
 .relic-cta{display:none;}
 .relic-title{display:none;}
 .hud-center{position:static;transform:none;order:2;margin:0 auto;}
 .hud-top{align-items:center;}
 .hud-left{order:1;}
 .hud-right{order:3;}
 #hint{display:none;}
 #weaponChip{bottom:calc(10px + env(safe-area-inset-bottom));padding:5px 8px;max-width:190px;}
 .chipico{width:26px;height:26px;}
 #weaponChip b{font-size:10px;max-width:120px;}
 #weaponChip small{font-size:7px;}
 #toasts{top:calc(72px + env(safe-area-inset-top));width:min(280px,76vw);}
}
@media (max-width: 620px) {
 .hud-left .bars{display:none;}
 .hud-center{position:absolute;left:50%;transform:translateX(-50%);}
 #timer{font-size:24px;}
 .hud-right{gap:5px;}
 #gold{padding:5px 7px;font-size:10px;}
 .iconbtn{width:32px;height:32px;}
 .menu-inner{padding-top:6px;}
 .lede{display:none;}
 .relics{gap:8px;}
 .endstats{grid-template-columns:repeat(2,1fr);}
 .stack.row{flex-direction:column;align-items:stretch;}
 .invhead h2{font-size:24px;}
 .invpanel{padding:14px;}
 .baggrid{grid-template-columns:repeat(5,1fr);gap:5px;}
 .slots{grid-template-columns:1fr 1fr;}
 .eqslot:nth-child(1){grid-column:span 2;}
 .statline{font-size:8px;}
 #bossbar{top:calc(60px + env(safe-area-inset-top));width:82vw;}
}
@media (max-height: 620px) and (orientation: landscape) {
 .menu-inner{padding:0;}
 .crest{display:none;}
 .title{font-size:clamp(40px,7vw,64px);}
 .tagline{margin:6px 0 2px;}
 .relic-label{margin:14px 0 8px;}
 .relic-desc{display:none;}
 .menu-foot{margin-top:12px;}
 .card{min-height:0;}
 .levelpanel{padding:14px;}
 .cards{max-height:46vh;}
}
